    }
    catch
    {
    }

    return "<!DOCTYPE html><html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8'/><title>DANH SÁCH VĂN BẰNG TỐT NGHIỆP</title></head><body><div class='subtitle'>{SUBTITLE}</div><div class='detail'>{DETAIL}</div></body></html>";
}

