    return strFileContent;
}

private void OpenExportInNewTab(string strHtml)
{
    string strPath = Server.MapPath("~");
    string strExportPath = strPath + "Export";
    string strFileNameSaveAs = String.Format("DanhSachVanBangTotNghiep_{0}_{1}.html",
        WebGlobal.FilterFileName(User.UserName),
        DateTime.Now.ToString("yyMMddHHmmss"));
    string strPathSaveAs = strExportPath + "\\" + strFileNameSaveAs;

    try
    {
        if (!Directory.Exists(strExportPath))
            Directory.CreateDirectory(strExportPath);

        File.WriteAllText(strPathSaveAs, strHtml, Encoding.UTF8);
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Không thể tạo file HTML xuất. " + ex.Message);
        return;
    }

    string strUrl = "/Export/" + strFileNameSaveAs
        + "?time=" + DateTime.Now.ToString("yyMMddHHmmss");

    ScriptManager.RegisterStartupScript(Page, Page.GetType(), "GraduationCerListExport",
        String.Format("window.open('{0}','_blank');", strUrl), true);
}

